           $$According to the lesson, how does the resulting history differ between a merge and a rebase?$$, NULL, NULL,
           $$Merge preserves exactly what happened, including a merge commit; rebase rewrites the branch's commits into a clean, linear story, at the cost of no longer perfectly reflecting what actually happened.$$, 'n8n-ai-judge', '2026-08-29 20:49:08.727617',
           now(), now()
    FROM topic
    WHERE slug = 'rebase-and-squash'
      AND NOT EXISTS (SELECT 1 FROM existing_q2)
