    INSERT INTO question_option (question_id, option_text, is_correct, sort_order)
    SELECT target_q2.id, v.option_text, v.is_correct, v.sort_order
    FROM target_q2
             CROSS JOIN (VALUES
    ($$Merge always produces a linear history, while rebase always produces a merge commit.$$, FALSE, 0),
    ($$Merge preserves exactly what happened, including a merge commit; rebase rewrites the branch's commits into a clean, linear story that no longer perfectly reflects what actually happened.$$, TRUE, 1),
    ($$Both produce identical histories — the only difference is which command you type.$$, FALSE, 2),
    ($$Rebase preserves the original commit hashes, while merge always creates new ones.$$, FALSE, 3)
        ) AS v(option_text, is_correct, sort_order)
    WHERE target_q2.newly_inserted
    RETURNING 1
)
