    ($$You should default to plain `--force` rather than `--force-with-lease` since it's simpler to type.$$, FALSE, 1),
    ($$Once a rebase conflict starts, aborting it is unsafe and should be avoided at all costs.$$, FALSE, 2),
    ($$A good practice is to use `git rebase -i` to squash 'fix typo'-style commits into their parent before requesting review.$$, TRUE, 3)
        ) AS v(option_text, is_correct, sort_order)
    WHERE target_q10.newly_inserted
    RETURNING 1
)
INSERT INTO quiz_question_link (quiz_id, question_id, position)
SELECT quiz.id, target_q10.id, 10
FROM target_q10
         JOIN quiz ON TRUE
         JOIN topic t ON t.id = quiz.topic_id
WHERE t.slug = 'rebase-and-squash'
  AND quiz.language = 'en'
  AND quiz.slug = 'default'
ON CONFLICT (quiz_id, question_id) DO NOTHING;

